import {arrivalCopy,arrivalContent} from './arrival.js';
import {createContactDates} from './contact-dates.js';
import {siteView} from './publication.js';
import {identityMarkup,syncIdentity} from './identity.js';
import {updateSeoDocument} from './seo.js';
import {amenityIcon} from './amenity-icons.js';
import {translateCs} from './i18n.js';
import {applyPhotoLibrary,apartmentPhotographs} from './photo-library.js';
import {createGuestView} from './host-tools.js';
import {createPlanning} from './planning.js';
import {restoreTextSize,applyTextSize} from './text-size.js';
import {createStayTools} from './stay-tools.js';
import {createFeatures} from './features.js';
'use strict';
restoreTextSize(document.documentElement);
const sourceSite=window.SITE=applyPhotoLibrary(window.SITE);
const S=siteView(sourceSite,()=>/^\/admin\/?$/.test(location.pathname));
let lang=new URLSearchParams(location.search).get('lang')||'hr';
if(!['hr','en','de','cs'].includes(lang))lang='hr';
const t=(hr,en,de,cs)=>lang==='cs'?(cs||translateCs(en??hr)):({hr,en,de}[lang]||hr);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'/',apartments:'/apartmani/',about:'/o-nama/',gallery:'/galerija/',contact:'/kontakt/',privacy:'/privatnost/',terms:'/uvjeti/'};
const url=(key)=>paths[key]||'/apartmani/'+key+'/';
const label=key=>({home:t('Naslovnica','Home','Startseite'),apartments:t('Apartmani','Apartments','Apartments'),about:t('O nama','Our story','Über uns'),gallery:t('Galerija','Gallery','Galerie'),contact:t('Kontakt','Contact','Kontakt')}[key]||key);
const cta=()=>t('Pošalji upit','Make an enquiry','Anfrage senden');
const pending=()=>t('Na upit','On request','Auf Anfrage');
const image=key=>S.photos.find(p=>p.key===key)||S.photos[0];
const photo=(key,cls='',eager=false)=>{const p=image(key);if(!p)return '';return `<img class="${cls}" src="${esc(p.url||'/assets/'+p.file)}" alt="${esc(t(p.alt,p.altEn||'Apartment photograph',p.altDe||'Apartmentfoto',p.altCs))}" ${eager?'fetchpriority="high"':'loading="lazy"'} width="1200" height="800">`};
function icon(name){const shapes={parking:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M9 17V7h4a3 3 0 0 1 0 6H9"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',sea:'<path d="M2 11c3-5 4 5 8 0s5 5 8 0 4 0 4 0M2 17c3-5 4 5 8 0s5 5 8 0 4 0 4 0M6 4h12"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',shop:'<path d="M4 10v11h16V10M3 4h18l1 6H2l1-6ZM9 21v-7h6v7M7 4l-1 6m6-6v6m5-6 1 6"/>',food:'<path d="M5 2v7c0 3 4 3 4 0V2M7 2v20M18 2c-4 5-4 10 0 10V2Zm0 10v10"/>',plane:'<path d="m22 2-7 20-4-9L2 9 22 2Zm-11 11L22 2"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 5a5 5 0 0 1 3 5"/>',bed:'<path d="M3 18V6m18 12V9M3 14h18M7 14V9h8a6 6 0 0 1 6 5M3 9h4m-4 9v3m18-3v3"/>',area:'<rect x="3" y="3" width="18" height="18" rx="1"/><path d="m7 17 10-10M7 11v6h6m-2-10h6v6"/>',leaf:'<path d="M20 3C8 1 1 9 6 16s16 3 14-13ZM5 21 17 8"/>',heart:'<path d="M20 5c-4-4-8 1-8 1S8 1 4 5c-5 5 8 15 8 15s13-10 8-15Z"/>',key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-3-3 3-3m-6 0 3-3"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9 10 10 0 0 1-4-1l-6 3 2-6a9 9 0 1 1 17-5Z"/>',quote:'<path d="M10 5H4v7h6v6H4m16-13h-6v7h6v6h-6"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.sun}</svg>`}
const F=createFeatures({S,t,esc,url,photo,icon,render,navigate,getLang:()=>lang,alternatives:data=>P.alternativeMarkup(data),whatsappLink:()=>C.waLink({apartment:S.apartments.find(a=>location.pathname.replace(/\/+$/,'')==='/apartmani/'+a.slug)?.slug||''})});
const G=createGuestView({t,esc,getLang:()=>lang,getSite:()=>S});
const P=createPlanning({S,t,esc,url,photo,getLang:()=>lang,navigate,getCalendar:()=>F.calendarData()});
const C=createStayTools({S,t,esc,url,photo,getLang:()=>lang,navigate});
function brand(){return identityMarkup(S,esc)}
function updateMenuSpace(){const nav=document.querySelector('.nav-links.open');if(!nav)return;const header=document.querySelector('.header'),bar=document.querySelector('.mobile-cta');const viewport=window.visualViewport?.height||window.innerHeight;const room=viewport-header.getBoundingClientRect().bottom-(bar?.getBoundingClientRect().height||0)-12;nav.style.setProperty('--menu-space',Math.max(80,Math.floor(room))+'px')}
function header(){return `<header class="header"><div class="wrap nav">${brand()}<nav class="nav-links" aria-label="${t('Glavna navigacija','Main navigation','Hauptnavigation')}"><details class="dropdown"><summary>${label('apartments')}</summary><div class="dropdown-menu"><a href="/pronadi-apartman/">${t('Pronađi apartman za mene','Find my apartment','Mein Apartment finden')} ↗</a><a href="/apartmani/">${t('Svi apartmani','All apartments','Alle Apartments')}</a><a href="/usporedba/">${t('Usporedi apartmane','Compare apartments','Apartments vergleichen')} ⇄</a>${S.apartments.map(a=>`<a href="${url(a.slug)}">${esc(a.name)}</a>`).join('')}</div></details>${window.MELEH_PORTAL?`<a href="/objekti" target="_self">${t('Odaberi objekt','Choose a property','Unterkunft wählen','Vybrat ubytování')}</a>`:''}${['about','gallery'].map(k=>`<a href="${url(k)}">${label(k)}</a>`).join('')}<a href="/vodic/">${t('Vodič','Guide','Reiseführer','Průvodce')}</a><a href="/kako-do-nas/">${t('Kako do nas','Getting here','Anreise','Jak se k nám dostat')}</a><a href="/kontakt/">${label('contact')}</a></nav><div class="nav-right"><details class="text-size-control"><summary aria-label="${t('Veličina teksta','Text size','Textgröße')}"><span aria-hidden="true">Aa</span></summary><div class="text-size-panel"><label for="text-size">${t('Veličina teksta','Text size','Textgröße')}</label><select id="text-size">${[['100',t('Uobičajeno','Standard','Standard')],['115',t('Veće','Larger','Größer')],['130',t('Vrlo veliko','Extra large','Sehr groß')],['150',t('Najveće','Largest','Am größten')]].map(([value,name])=>`<option value="${value}" ${document.documentElement.dataset.textSize===value?'selected':''}>${name} · ${value}%</option>`).join('')}</select><p>${t('Odabir se pamti na ovom uređaju.','Your choice is saved on this device.','Die Auswahl wird auf diesem Gerät gespeichert.')}</p></div></details><select class="language" aria-label="${t('Jezik','Language','Sprache')}">${['hr','en','de','cs'].map(l=>`<option value="${l}" ${lang===l?'selected':''}>${l.toUpperCase()}</option>`).join('')}</select><a class="btn" href="/kontakt/">${cta()} <span>↗</span></a><button class="menu-button" aria-expanded="false" aria-label="${t('Otvori izbornik','Open menu','Menü öffnen')}">☰</button></div></div></header>`}
function footer(){return `<section class="cta-band"><div class="wrap cta-inner"><div><h2>${t('Vaš odmor počinje jednom porukom.','Your holiday begins with a message.','Ihr Urlaub beginnt mit einer Nachricht.')}</h2><p>${t('Recite nam kada biste došli. Zajedno ćemo pronaći vaš kutak za odmor.','Tell us when you would like to visit. Let’s find your place to unwind.','Sagen Sie uns, wann Sie kommen möchten. Finden wir Ihren Ort zum Entspannen.')}</p></div><a class="btn light" href="/kontakt/">${cta()} <span>↗</span></a></div></section><footer class="footer"><div class="wrap"><div class="footer-grid"><div>${brand()}<p>${t(`Prostor za opuštanje. Vrijeme za vaše najdraže. Provedite odmor u svom ritmu u apartmanima ${esc(S.name)}.`,`Space to unwind. Time for the people you love. Enjoy a holiday at your pace at ${esc(S.name)}.`,`Raum zum Entspannen. Zeit für Ihre Liebsten. Genießen Sie Ihren Urlaub im eigenen Rhythmus in ${esc(S.name)}.`)}</p></div><div><h3>${label('apartments')}</h3><div class="footer-links">${S.apartments.map(a=>`<a href="${url(a.slug)}">${t('Apartman','Apartment','Apartment')} ${a.name}</a>`).join('')}<a href="/usporedba/">${t('Usporedi apartmane','Compare apartments','Apartments vergleichen')} ⇄</a></div></div><div><h3>${t('Istražite','Explore','Entdecken')}</h3><div class="footer-links">${['about','gallery','contact'].map(k=>`<a href="${url(k)}">${label(k)}</a>`).join('')}<a href="/vodic/">${t('Vodič','Guide','Reiseführer','Průvodce')}</a><a href="/kako-do-nas/">${t('Kako do nas','Getting here','Anreise','Jak se k nám dostat')}</a><a href="/faq/">${t('Česta pitanja','FAQ','Häufige Fragen')}</a><a href="/dostupnost/">${t('Dostupnost','Availability','Verfügbarkeit')}</a><a href="/pronadi-apartman/">${t('Pronađi apartman','Find an apartment','Apartment finden')}</a><a href="/admin/">${t('Za domaćina','Host access','Für Gastgeber')}</a>${S.instagram?`<a href="${esc(S.instagram)}">Instagram ↗</a>`:''}${S.facebook?`<a href="${esc(S.facebook)}">Facebook ↗</a>`:''}</div></div><div><h3>${label('contact')}</h3><div class="footer-links">${S.address?esc(S.address):t('Adresa će biti dodana','Address to be added','Adresse folgt')}${S.phone?`<a href="tel:${esc(S.phone)}">${esc(S.phone)}</a>`:`<span>${t('Telefon uskoro','Phone coming soon','Telefon folgt')}</span>`}</div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${esc(S.name)} · ${t('Odmor u svom ritmu.','A stay at your own pace.','Urlaub in Ihrem Rhythmus.')}</span><div><a href="/privatnost/">${t('Privatnost','Privacy','Datenschutz')}</a><a href="/uvjeti/">${t('Uvjeti korištenja','Terms of use','Nutzungsbedingungen')}</a></div></div></div></footer>${F.mobileBar()}`}
function specs(a){return `<div class="specs"><span>${icon('people')}${a.guests} ${t('osobe','guests','Personen')}</span><span>${icon('bed')}${a.rooms} ${t(a.rooms===1?'soba':'sobe',a.rooms===1?'bedroom':'bedrooms',a.rooms===1?'Schlafzimmer':'Schlafzimmer')}</span><span>${icon('area')}${a.area} m²</span></div>`}
function description(a){return F.tr(a.description)?esc(F.tr(a.description).slice(0,185)):esc(t('Apartman ','Apartment ','Apartment ')+a.name)}
function cards(){if(!S.apartments.length)return `<p class="section-note">${t('Trenutačno nema objavljenih apartmana. Za informacije o smještaju kontaktirajte nas.','No apartments are currently published. Contact us for accommodation information.','Derzeit sind keine Apartments veröffentlicht. Kontaktieren Sie uns für Informationen.')}</p>`;return `<div class="apartments-grid">${S.apartments.map((a,i)=>`<article class="apartment-card"><a class="image-wrap" href="${url(a.slug)}">${photo(a.image)}<span class="image-label">${t('APARTMAN','APARTMENT','APARTMENT')} ${esc(a.name)}</span></a><div class="card-body"><div class="card-title"><h3><a href="${url(a.slug)}">${a.name}</a></h3></div>${specs(a)}<p>${description(a)}</p><a class="text-link" href="${url(a.slug)}">${t('Pogledaj apartman','Explore apartment','Apartment ansehen')} <span>↗</span></a>${C.cardLink(a)}</div></article>`).join('')}</div>`}
function map(){return S.mapEmbed?`<iframe title="${t('Lokacija objekta','Property location','Lage der Unterkunft')}" src="${esc(S.mapEmbed)}" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe>`:`<div class="map-placeholder"><div class="map-center">${icon('pin')}<h3>${t('Luka Dubrava · Pelješac','Luka Dubrava · Pelješac','Luka Dubrava · Pelješac')}</h3><p>${esc(S.address||'Luka Dubrava 28, 20248 Dubrava, Pelješac')}</p><a class="btn" href="${esc(S.mapsUrl||'https://goo.gl/maps/8DoVQCfixUfhY4me8')}" target="_blank" rel="noopener noreferrer">${t('Otvori točnu lokaciju','Open exact location','Genauen Standort öffnen')} ↗</a></div></div>`}
function locationSection(){return `<section class="section cream"><div class="wrap location-grid"><div><span class="eyebrow">${t('PRONAĐITE NAS','FIND US','FINDEN SIE UNS')}</span><h2>${t('Korak bliže<br>vašem odmoru.','One step closer<br>to your holiday.','Ein Schritt näher<br>an Ihrem Urlaub.')}</h2><p>${S.location?esc(S.location):t('Ovdje ćemo podijeliti našu lokaciju, preporuke za dolazak automobilom i informacije o najbližoj zračnoj luci ili trajektnoj luci.','Here we will share our location, driving directions and information about the nearest airport or ferry port.','Hier finden Sie bald unseren Standort, die Anreise mit dem Auto sowie Informationen zum nächsten Flughafen oder Fährhafen.')}</p>${S.mapsUrl?`<a class="text-link" href="${esc(S.mapsUrl)}" target="_blank" rel="noopener">Google Maps ↗</a>`:`<a class="text-link" href="/kontakt/">${t('Javite nam se','Get in touch','Kontakt aufnehmen')} ↗</a>`}</div>${map()}</div></section>`}
function surroundings(){
 const rows=[
  ['sea','beach',t('Plaža i more','Beach & sea','Strand & Meer'),t('Istražite plaže Pelješca.','Explore Pelješac’s beaches.','Entdecken Sie die Strände von Pelješac.'),t('Pronađi plažu','Find a beach','Strand finden')],
  ['pin','center',t('Centar mjesta','Town centre','Ortszentrum'),t('Upoznajte mjesto i uvalu Luka Dubrava.','Explore Luka Dubrava village and bay.','Entdecken Sie den Ort und die Bucht Luka Dubrava.'),t('Otvori centar','View town centre','Zentrum ansehen')],
  ['shop','shop',t('Trgovina','Grocery shops','Lebensmittel'),t('Trgovine za svakodnevnu kupnju.','Shops for your everyday essentials.','Geschäfte für den täglichen Bedarf.'),t('Pronađi trgovinu','Find a shop','Geschäft finden')],
  ['food','restaurant',t('Restoran','Restaurants','Restaurants'),t('Istražite restorane i lokalne okuse.','Explore restaurants and local flavours.','Entdecken Sie Restaurants und lokale Küche.'),t('Pronađi restoran','Find a restaurant','Restaurant finden')],
  ['plane','airport',t('Zračna luka','Airport','Flughafen'),t('Zračna luka Dubrovnik · Čilipi.','Dubrovnik Airport · Čilipi.','Flughafen Dubrovnik · Čilipi.'),t('Otvori lokaciju','View location','Standort ansehen')],
  ['parking','parking',t('Parking','Parking','Parken'),t('Parking za goste nalazi se ispred kuće.','Guest parking is in front of the house.','Gästeparkplätze befinden sich vor dem Haus.'),t('Dolazak do kuće','Directions to the house','Anfahrt zum Haus')]
 ];
 return `<div class="distances" id="okolica">${rows.map(([i,k,title,description,action])=>`<article class="distance">${icon(i)}<h3>${title}</h3><p>${description}</p><small class="distance-detail"${S.distances?.[k]?'':' aria-hidden="true"'}>${S.distances?.[k]?esc(lang==='cs'?translateCs(S.distances[k]):S.distances[k]):''}</small>${S.distanceLinks?.[k]?`<div class="distance-actions"><a href="${esc(S.distanceLinks[k])}" target="_blank" rel="noopener noreferrer"><span class="distance-link-label">${action}</span><span class="distance-arrow" aria-hidden="true">↗</span></a></div>`:''}</article>`).join('')}</div>`;
}
function home(){return `<section class="hero">${photo(S.heroImage||'hero','',true)}<div class="wrap hero-content"><span class="eyebrow">${t('MALI BIJEG. VELIKE USPOMENE.','A LITTLE ESCAPE. LASTING MEMORIES.','KLEINE AUSZEIT. GROSSE ERINNERUNGEN.')}</span><h1>${t('Odmor.<br>U vašem <em>ritmu.</em>','A holiday.<br>At your <em>pace.</em>','Urlaub.<br>In Ihrem <em>Rhythmus.</em>')}</h1><p>${t(`Jutra bez žurbe. Dani ispunjeni suncem.<br>Pronađite svoj kutak za odmor u apartmanima ${esc(S.name)}.`,`Unhurried mornings. Sun-filled days.<br>Find your place to unwind at ${esc(S.name)}.`,`Morgen ohne Eile. Tage voller Sonne.<br>Finden Sie Ihren Rückzugsort in ${esc(S.name)}.`)}</p><a class="btn light" href="/apartmani/">${t('Istražite apartmane','Explore apartments','Apartments entdecken')} <span>↗</span></a></div><div class="hero-bottom"><span>${t('LUKA DUBRAVA · PELJEŠAC','LUKA DUBRAVA · PELJEŠAC','LUKA DUBRAVA · PELJEŠAC')}</span><span>${t('ISTRAŽITE','EXPLORE','ENTDECKEN')} <span>↓</span></span></div></section><section class="availability"><div class="wrap"><form id="availability"><div><label for="quick-in">${t('DATUM DOLASKA','CHECK-IN','ANREISE')}</label><input id="quick-in" name="arrival" type="date" required></div><div><label for="quick-out">${t('DATUM ODLASKA','CHECK-OUT','ABREISE')}</label><input id="quick-out" name="departure" type="date" required></div><div><label for="quick-guests">${t('BROJ OSOBA','GUESTS','PERSONEN')}</label><select name="adults" id="quick-guests">${[1,2,3,4,5].map(n=>`<option ${n===2?'selected':''} value="${n}">${n} ${t(n===1?'osoba':n<5?'osobe':'osoba',n===1?'guest':'guests',n===1?'Person':'Personen',n===1?'host':n<5?'hosté':'hostů')}</option>`).join('')}</select></div><button class="btn" type="submit">${t('Upit za dostupnost','Enquire about availability','Verfügbarkeit anfragen')} <span>↗</span></button></form></div></section><section class="section"><div class="wrap"><div class="intro"><div class="intro-photo">${photo(S.introImage||'beach')}<div class="photo-label">${t('Manje žurbe.<br>Više uživanja.','Slow down.<br>Settle in.','Weniger Eile.<br>Mehr genießen.')}</div></div><div class="intro-copy"><span class="eyebrow">${t(`DOBRO DOŠLI · ${esc(S.name)}`,`WELCOME · ${esc(S.name)}`,`WILLKOMMEN · ${esc(S.name)}`)}</span><h2>${t('Mjesto u kojem<br>vrijeme usporava.','A place where<br>time slows down.','Ein Ort, an dem<br>die Zeit langsamer wird.')}</h2><p>${t('Najljepši odmor čine jednostavne stvari: prva jutarnja kava, dobra knjiga i vrijeme s ljudima koje volite. Pronađite svoj kutak za odmor uz more na Pelješcu.','The best holidays are made of simple things: the first coffee of the day, a good book and time with the people you love. Let this be your first step towards that kind of stay.','Die schönsten Urlaubstage bestehen aus einfachen Dingen: dem ersten Kaffee, einem guten Buch und Zeit mit Ihren Liebsten. Hier beginnt die Vorfreude darauf.')}</p><a class="text-link" href="/o-nama/">${t('Upoznajte našu priču','Discover our story','Unsere Geschichte entdecken')} ↗</a><p class="small-note">${t('Šest klimatiziranih apartmana, besplatan Wi-Fi i privatni parking. More je udaljeno 10 m.','Six air-conditioned apartments, free Wi-Fi and private parking. The sea is 10 m away.','Sechs klimatisierte Apartments, kostenloses WLAN und Privatparkplätze. Das Meer ist 10 m entfernt.')}</p></div></div>${surroundings()}</div></section><section class="section cream"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">${t('PROSTOR ZA VAŠ ODMOR','ROOM TO UNWIND','RAUM FÜR IHREN URLAUB')}</span><h2>${t('Pronađite svoj apartman.','Find your apartment.','Finden Sie Ihr Apartment.')}</h2></div><p>${t('Za jutra udvoje ili druženja s najdražima.<br>Odaberite prostor koji prati vaš ritam.','For mornings together or time with the family.<br>Choose a space that feels like you.','Für Zeit zu zweit oder mit der Familie.<br>Wählen Sie Ihren Lieblingsplatz.')}</p></div>${cards()}</div></section><section class="section"><div class="wrap benefits"><div><span class="eyebrow">${t('JEDNOSTAVNO. OSOBNO. OPUŠTENO.','SIMPLE. PERSONAL. RELAXED.','EINFACH. PERSÖNLICH. ENTSPANNT.')}</span><h2>${t('Mali detalji.<br>Lijep osjećaj odmora.','Little details.<br>A lovely feeling.','Kleine Details.<br>Ein schönes Urlaubsgefühl.')}</h2></div><div class="benefit-grid">${[['chat',t('Direktan dogovor','A direct conversation','Direkter Kontakt'),t('Pošaljite svoje želje i pitanja u jednom upitu.','Share your wishes and questions in one enquiry.','Teilen Sie Ihre Wünsche und Fragen in einer Anfrage.')],['key',t('Prostor po vašoj mjeri','A space that suits you','Raum nach Ihren Wünschen'),t('Usporedite apartmane i pronađite svoj favorit.','Compare apartments and find your favourite.','Vergleichen Sie die Apartments und finden Sie Ihren Favoriten.')],['heart',t('Vrijeme za vaše ljude','Time for your people','Zeit für Ihre Liebsten'),t('Za zajedničke trenutke koji postaju najljepše uspomene.','For shared moments that turn into favourite memories.','Für gemeinsame Momente und schöne Erinnerungen.')],['leaf',t('Inspirirano Mediteranom','Mediterranean inspiration','Mediterrane Inspiration'),t('Prirodni tonovi i opušten duh odmora.','Natural tones and an easy holiday spirit.','Natürliche Farben und entspannte Urlaubsstimmung.')]].map(([i,h,p])=>`<div class="benefit-item">${icon(i)}<h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div></section><section class="wide-photo">${photo(S.bannerImage||'sunset')}<div><span class="eyebrow">${t('UHVATITE TRENUTAK','SAVOUR THE MOMENT','DEN MOMENT GENIESSEN')}</span><h2>${t('Nigdje ne morate biti.<br>Osim ovdje.','Nowhere you need to be.<br>Except here.','Nirgendwo sein müssen.<br>Außer hier.')}</h2><p>${t('Plaža i more uz kuću u Luci Dubravi.','The beach and sea by the house in Luka Dubrava.','Strand und Meer am Haus in Luka Dubrava.','Pláž a moře u domu v Luce Dubravě.')}</p></div></section>${F.homeExtras()}${P.homeLinks()}${locationSection()}`}
function pageHead(title,sub='',parent=''){return `<section class="page-head"><div class="wrap"><div class="breadcrumbs"><a href="/">${label('home')}</a> / ${parent?`<a href="/apartmani/">${label('apartments')}</a> / `:''}${title}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div></section>`}
function apartments(){return `${pageHead(label('apartments'),t('Šest apartmana u Luci Dubravi. Usporedite kapacitet, broj soba i površinu te odaberite svoj favorit.','Six apartments in Luka Dubrava. Compare capacity, bedrooms and floor area to find your favourite.','Sechs Apartments in Luka Dubrava. Vergleichen Sie Kapazität, Schlafzimmer und Fläche.'))}<section class="section"><div class="wrap"><div class="compare-intro"><p>${t('Kapacitet, raspored i cijene na jednom mjestu.','Capacity, layout and prices in one place.','Kapazität, Aufteilung und Preise auf einen Blick.')}</p><a class="btn outline" href="/usporedba/">${t('Usporedi apartmane','Compare apartments','Apartments vergleichen')} ⇄</a></div>${cards()}</div></section>`}
function apartmentGallery(a){const photos=apartmentPhotographs(S,a.slug);if(!photos.length)return '';return `<section class="apartment-photo-section"><div class="section-heading"><div><h2>${t('Istražite apartman ','Explore apartment ','Apartment entdecken: ')}${esc(a.name)}</h2></div><p>${photos.length} ${t('fotografija ovog apartmana. Kliknite za veći prikaz.','photographs of this apartment. Click to enlarge.','Fotos dieses Apartments. Zum Vergrößern anklicken.')}</p></div><div class="gallery-grid">${photos.map(p=>`<button class="gallery-item" data-photo="${p.key}" aria-label="${esc(t(p.alt,p.altEn,p.altDe))}">${photo(p.key)}<span>${esc(a.name)} ↗</span></button>`).join('')}</div></section>`}
function detail(a){const actual=apartmentPhotographs(S,a.slug),secondary=actual.find(p=>p.key!==a.image)?.key||a.image;return `${pageHead(t('Apartman ','Apartment ','Apartment ')+a.name, t('Fotografije ovog apartmana.','Photographs of this apartment.','Fotos dieses Apartments.'),'apartments')}<section class="section" style="padding-top:35px"><div class="wrap">${specs(a)}<div class="detail-gallery"><button data-photo="${a.image}">${photo(a.image,'',true)}<span>${t('Uvećaj fotografiju','Enlarge photo','Foto vergrößern')} ⤢</span></button><button data-photo="${secondary}">${photo(secondary)}<span>${t('Pogledaj fotografije','View photographs','Fotos ansehen')} ↗</span></button></div><div class="detail-layout"><div class="detail-copy"><section><span class="eyebrow">${t('VAŠ PROSTOR ZA ODMOR','YOUR PLACE TO UNWIND','IHR ORT ZUM ENTSPANNEN')}</span><h2>${a.type==='family'?t('Zajedno je najljepše.','Better together.','Zusammen ist es am schönsten.'):t('Usporite. Ovdje ste.','Slow down. You’re here.','Entspannen Sie. Sie sind hier.')}</h2><p>${F.tr(a.description)?esc(F.tr(a.description)):description(a)}</p><p>${t(`Kapacitet: ${a.guests.split('+')[0].trim()} osnovna ležaja${a.guests.includes('+')?' + '+a.guests.split('+')[1].trim()+' dodatni ležaj':''}.`,`Capacity: ${a.guests.split('+')[0].trim()} standard beds${a.guests.includes('+')?' + '+a.guests.split('+')[1].trim()+' extra bed':''}.`,`Kapazität: ${a.guests.split('+')[0].trim()} reguläre Schlafplätze${a.guests.includes('+')?' + '+a.guests.split('+')[1].trim()+' Zusatzbett':''}.`)}</p></section><section><h2>${t('Sve za ugodan boravak.','Everything for a lovely stay.','Alles für einen schönen Aufenthalt.')}</h2><dl class="planner-amenities">${P.badges(a)}</dl></section><section><h2>${t('Dobro je znati.','Good to know.','Gut zu wissen.')}</h2><div class="rule-list">${[[t('Prijava','Check-in','Anreise'),S.checkIn,'checkIn'],[t('Odjava','Check-out','Abreise'),S.checkOut,'checkOut'],[t('Kućni ljubimci','Pets','Haustiere'),a.petFee!=null?t('Dopušteni · '+a.petFee+' € / dan','Allowed · €'+a.petFee+' / day','Erlaubt · '+a.petFee+' € / Tag'):S.pets,'pets'],[t('Minimalni boravak','Minimum stay','Mindestaufenthalt'),(a.minNights||1)+' '+t(a.minNights===1?'noć':'noći',a.minNights===1?'night':'nights',a.minNights===1?'Nacht':'Nächte'),'minNights'],[t('Dan dolaska','Arrival day','Anreisetag'),F.tr(S.arrivalDays),'arrivalDay'],[t('Boravišna pristojba','Tourist tax','Kurtaxe'),S.touristTaxIncluded?t('Uključena u cijenu','Included in the price','Im Preis enthalten'):pending(),'touristTax'],[t('Pušenje','Smoking','Rauchen'),S.smoking==='Pušenje nije dopušteno u apartmanu. Dopušteno je na balkonu ili terasi.'?t('Pušenje nije dopušteno u apartmanu. Dopušteno je na balkonu ili terasi.','Smoking is not permitted inside the apartment. It is permitted on the balcony or terrace.','Das Rauchen ist im Apartment nicht gestattet. Auf dem Balkon oder der Terrasse ist es erlaubt.','Kouření uvnitř apartmánu není dovoleno. Kouřit lze na balkoně nebo terase.'):S.smoking,'smoking']].map(([k,v,rule])=>`<div><strong class="amenity-label">${amenityIcon(rule)}<span>${k}</span></strong><span>${v||pending()}</span></div>`).join('')}</div></section></div><aside class="booking-box"><span class="eyebrow">${t('PLANIRAJTE BORAVAK','PLAN YOUR STAY','PLANEN SIE IHREN AUFENTHALT')}</span><h3>${t('Vaši datumi.<br>Vaš odmor.','Your dates.<br>Your holiday.','Ihre Reisedaten.<br>Ihr Urlaub.')}</h3><p>${t('Pregledajte sezonski cjenik niže na stranici. Za svoj termin pripremite upit s datumima i brojem gostiju.','See the seasonal prices below. Prepare an enquiry with your dates and guest numbers.','Die Saisonpreise finden Sie unten. Bereiten Sie eine Anfrage mit Reisedaten und Gästezahl vor.')}</p><a class="btn" href="/kontakt/?apartman=${a.slug}">${cta()} ↗</a>${C.waLink({apartment:a.slug})}${C.cardLink(a)}<p class="section-note">${t('Dostupnost se potvrđuje osobnim dogovorom. Slanje upita nije rezervacija.','Availability is confirmed personally. An enquiry is not a reservation.','Die Verfügbarkeit wird persönlich bestätigt. Eine Anfrage ist keine Buchung.')}</p></aside></div>${apartmentGallery(a)}</div></section>${F.apartmentExtras(a)}`}
function about(){return `${pageHead(label('about'),t('Dobar odmor počinje osjećajem dobrodošlice.','A good holiday starts with feeling welcome.','Ein schöner Urlaub beginnt mit einem herzlichen Willkommen.'))}<section class="section"><div class="wrap"><div class="intro"><div class="intro-photo">${photo(S.introImage||'beach')}<div class="photo-label">${t('S pažnjom<br>prema detaljima.','A little care.<br>In every detail.','Mit Liebe<br>zum Detail.')}</div></div><div class="intro-copy"><span class="eyebrow">${t('NAŠA PRIČA','OUR STORY','UNSERE GESCHICHTE')}</span><h2>${t('Odmor kojem se<br>želite vratiti.','A stay you’ll want<br>to return to.','Ein Urlaub, zu dem<br>Sie zurückkehren möchten.')}</h2><p>${t(`U ${esc(S.name)} uživajte u opuštenim jutrima i vremenu koje pripada samo vama. Za pitanja o boravku obratite se izravno domaćinu.`,`Enjoy relaxed mornings and time to yourself at ${esc(S.name)}. Contact your host directly with any questions about your stay.`,`Genießen Sie entspannte Morgen und Zeit für sich in ${esc(S.name)}. Bei Fragen zu Ihrem Aufenthalt wenden Sie sich direkt an Ihren Gastgeber.`)}</p><p>${F.tr(S.aboutText)?esc(F.tr(S.aboutText)):t('Za dodatna pitanja o boravku kontaktirajte domaćina.','Contact your host with any further questions about your stay.','Bei weiteren Fragen zu Ihrem Aufenthalt kontaktieren Sie Ihren Gastgeber.')}</p><span class="signature">${esc(S.name)}</span></div></div><div class="about-values">${[[t('Osobno','Personal','Persönlich'),t('Prostor za vaša pitanja, želje i detalje koji su vam važni.','Room for your questions, wishes and the details that matter to you.','Platz für Ihre Fragen, Wünsche und wichtige Details.')],[t('Jednostavno','Simple','Einfach'),t('Jasne informacije i direktan kontakt za dogovor o boravku.','Clear information and direct contact to arrange your stay.','Klare Informationen und direkter Kontakt für Ihren Aufenthalt.')],[t('Opušteno','Relaxed','Entspannt'),t('Inspiracija za dane u kojima ne morate gledati na sat.','Inspiration for days when there’s no need to watch the clock.','Inspiration für Tage, an denen die Uhr keine Rolle spielt.')]].map(([h,p])=>`<div><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div></section>${propertyDetails()}`}
const categories=()=>[['house',t('Kuća i okućnica','House & garden','Haus & Garten','Dům a zahrada')],['location',t('Lokacija i plaže','Location & beaches','Lage & Strände','Poloha a pláže')],...S.apartments.map(a=>[a.slug,a.name])];
function photoSummary(){return t('Istražite kuću, plaže i apartmane kroz zasebne fotoalbume.','Explore the house, beaches and apartments in separate photo albums.','Entdecken Sie Haus, Strände und Apartments in eigenen Fotoalben.','Prohlédněte si dům, pláže a apartmány v samostatných fotoalbech.')}
function gallery(){return `${pageHead(label('gallery'),photoSummary())}<section class="section" style="padding-top:40px"><div class="wrap"><div class="album-grid">${categories().map(([category,title])=>{const photos=S.photos.filter(p=>p.category===category);if(!photos.length)return '';const preferred=category==='house'?S.introImage:category==='location'?S.bannerImage:null;const cover=photos.find(p=>p.key===preferred)||photos[0];return `<button class="gallery-album" data-album="${esc(category)}" aria-label="${esc(title+' — '+t('Otvori album','Open album','Album öffnen','Otevřít album'))}"><div class="album-cover">${photo(cover.key)}<span class="album-count">${t('Fotografije','Photos','Fotos','Fotografie')}: ${photos.length}</span></div><div class="album-body"><h2>${esc(title)}</h2><span class="album-action">${t('Otvori album','Open album','Album öffnen','Otevřít album')} <span aria-hidden="true">↗</span></span></div></button>`}).join('')}</div></div></section>`}
const contactDates=createContactDates({getLanguage:()=>lang,getCalendarData:()=>F.calendarData(),getToday:today,getQuery:()=>new URLSearchParams(location.search)});
function contact(){return `${pageHead(label('contact'),t('Planirate odmor u Luci Dubravi? Nazovite domaćicu ili pripremite upit za željene datume.','Planning a stay in Luka Dubrava? Call your host or prepare an enquiry for your preferred dates.','Planen Sie Urlaub in Luka Dubrava? Rufen Sie Ihre Gastgeberin an oder bereiten Sie eine Anfrage für Ihre Reisedaten vor.'))}<section class="section"><div class="wrap contact-grid"><div><form id="inquiry" class="form-grid"><label class="field">${t('Ime i prezime','Full name','Vor- und Nachname')} *<input name="name" required autocomplete="name" maxlength="120" placeholder="${t('Vaše ime i prezime','Your full name','Ihr vollständiger Name')}"></label><label class="field">${t('E-mail adresa','Email address','E-Mail-Adresse')} *<input name="email" required type="email" autocomplete="email" maxlength="200" placeholder="${t('ime@primjer.hr','name@example.com','name@beispiel.de','jmeno@priklad.cz')}"></label><label class="field">${t('Telefon / WhatsApp','Phone / WhatsApp','Telefon / WhatsApp')}<input name="phone" type="tel" autocomplete="tel" maxlength="50" placeholder="+385 …"></label><label class="field">${t('Željeni apartman','Preferred apartment','Gewünschtes Apartment')}<select name="apartment"><option value="">${t('Nisam siguran / Svejedno','Not sure / Any apartment','Noch unsicher / Egal')}</option>${S.apartments.map(a=>`<option value="${a.slug}">${a.name}</option>`).join('')}</select></label>${contactDates.markup()}<label class="field">${t('Odrasli','Adults','Erwachsene')} *<input name="adults" type="number" min="1" max="40" value="2" required></label><label class="field">${t('Djeca','Children','Kinder')}<input name="children" type="number" min="0" max="40" value="0"></label><label class="field full">${t('Vaša poruka','Your message','Ihre Nachricht')}<textarea name="message" maxlength="5000" placeholder="${t('Vaše želje, pitanja ili nešto što bismo trebali znati…','Your wishes, questions or anything we should know…','Ihre Wünsche, Fragen oder weitere Informationen…')}"></textarea></label><div class="hp-field" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="consent full"><input type="checkbox" required name="consent"><span>${t('Pročitao/la sam','I have read the','Ich habe die')} <a href="/privatnost/" style="text-decoration:underline">${t('pravila privatnosti','privacy notice','Datenschutzhinweise')}</a>. ${F.mailReady?t('Pristajem na obradu podataka radi odgovora na upit i slanje potvrde primitka.','I agree to data processing to answer my enquiry and send an acknowledgement.','Ich stimme der Verarbeitung zur Beantwortung meiner Anfrage und zum Versand einer Eingangsbestätigung zu.'):t('Razumijem da se upit priprema u mojem pregledniku i ne šalje automatski.','I understand that my enquiry is prepared in my browser and is not sent automatically.','Ich verstehe, dass meine Anfrage in meinem Browser vorbereitet und nicht automatisch versendet wird.')}</span></label><div class="full"><button class="btn" type="submit">${F.mailReady?cta():t('Pripremi upit','Prepare enquiry','Anfrage vorbereiten')} ↗</button><p class="section-note">${F.mailReady?t('Upit nije rezervacija. Podaci se koriste za odgovor domaćina.','An enquiry is not a reservation. Your details are used for the host’s reply.','Eine Anfrage ist keine Buchung. Ihre Angaben dienen der Antwort des Gastgebers.'):t('Bez obveze rezervacije. Osobni podaci ne spremaju se na poslužitelj.','No reservation commitment. Personal details are not stored on a server.','Keine verbindliche Buchung. Persönliche Angaben werden nicht auf einem Server gespeichert.')}</p><p class="form-error" id="form-error" role="alert"></p></div></form><div id="inquiry-result" aria-live="polite"></div></div><aside class="contact-aside"><h3>${t('Radujemo se vašoj poruci.','We look forward to your message.','Wir freuen uns auf Ihre Nachricht.')}</h3><div class="contact-detail"><strong>${t('Adresa','Address','Adresse')}</strong><p>${esc(S.address)||pending()}</p></div><div class="contact-detail"><strong>${t('Telefon','Phone','Telefon')}</strong><p>${S.phone?`<a href="tel:${esc(S.phone)}">${esc(S.phone)}</a>`:pending()}</p></div>${C.contactPanel()}${S.viber?`<a class="btn outline" href="viber://chat?number=${encodeURIComponent(S.viber)}">Viber ↗</a>`:''}</aside></div></section>${locationSection()}`}
function legal(kind){const privacy=kind==='privacy';return `${pageHead(privacy?t('Pravila privatnosti','Privacy notice','Datenschutzhinweise'):t('Uvjeti korištenja','Terms of use','Nutzungsbedingungen'))}<section class="section"><div class="wrap legal">${privacy?`<h2>${t('Vaši osobni podaci','Your personal data','Ihre personenbezogenen Daten')}</h2><p>${F.privacyNotice()||t('Obrazac obrađuje unesene podatke samo u vašem pregledniku radi pripreme teksta upita. Ova stranica ne šalje obrazac domaćinu i ne sprema njegove podatke na poslužitelj. Kopirani tekst ili preuzetu datoteku šaljete sami odabranom primatelju.','The form processes your entries in your browser to prepare an enquiry. It does not send the form to a host or store form details on a server. You choose whether to send copied text or a downloaded file to a recipient.','Das Formular verarbeitet Ihre Angaben im Browser, um eine Anfrage vorzubereiten. Es sendet sie nicht an Gastgeber und speichert Formulardaten nicht auf einem Server. Kopierten Text oder eine heruntergeladene Datei versenden Sie selbst.')}</p><h2>${t('Postavke i vanjski sadržaj','Preferences and external content','Einstellungen und externe Inhalte')}</h2><p>${t('U lokalnu pohranu preglednika spremamo odabrani jezik i veličinu teksta. Ne koristimo analitičke alate ni marketinške kolačiće. Fontovi se učitavaju preko Google Fonts usluge, pri čemu Google prima tehničke podatke veze poput IP adrese. Hosting također obrađuje tehničke podatke potrebne za dostavu stranice.','Your language and text size preferences are saved in browser local storage. We use no analytics or marketing cookies. Fonts are loaded via Google Fonts, which receives technical connection data such as your IP address. Hosting also processes technical data needed to deliver the site.','Im lokalen Browserspeicher speichern wir Ihre Sprachwahl und die Textgröße. Wir verwenden keine Analyse- oder Marketing-Cookies. Schriftarten werden über Google Fonts geladen; Google erhält dabei technische Verbindungsdaten wie die IP-Adresse. Das Hosting verarbeitet ebenfalls zur Bereitstellung notwendige technische Daten.')}</p><h2>${t('Kalendar i privatni vodič','Calendar and private guide','Kalender und privater Reiseführer')}</h2><p>${t('Javni kalendar prikazuje samo razdoblja zauzeća, bez imena gostiju i privatnih bilješki. Privatni vodič s uputama za boravak dostupan je putem tajne poveznice koju gostu dijeli domaćin nakon potvrde boravka. Poveznica istječe nakon boravka i može se opozvati.','The public calendar shows occupied periods only, without guest names or private notes. The private stay guide is available through a secret link shared by the host after confirmation. The link expires after the stay and can be revoked.','Der öffentliche Kalender zeigt nur Belegungszeiträume, ohne Gästenamen oder private Notizen. Der private Aufenthaltsführer ist über einen geheimen Link zugänglich, den der Gastgeber nach Bestätigung teilt. Der Link endet nach dem Aufenthalt und kann widerrufen werden.')}</p><h2>WhatsApp</h2><p>${t('WhatsApp se otvara tek kada kliknete poveznicu. Pripremljeni tekst upita tada se prenosi WhatsAppu, gdje ga možete urediti i sami poslati. Sadržaj poruke i kontaktne podatke obrađuje WhatsApp prema svojim pravilima privatnosti.','WhatsApp opens only when you click its link. The prepared enquiry text is then passed to WhatsApp, where you can edit and send it yourself. WhatsApp processes the message and contact details under its own privacy policy.','WhatsApp öffnet sich erst beim Klick auf den Link. Der vorbereitete Anfragetext wird an WhatsApp übergeben und kann dort bearbeitet und selbst versendet werden. WhatsApp verarbeitet Nachricht und Kontaktdaten nach seinen Datenschutzbestimmungen.')}</p><h2>${t('Pitanja o privatnosti','Privacy questions','Fragen zum Datenschutz')}</h2><p>${t('Za pitanja o obradi vaših podataka obratite se domaćinu putem telefona navedenog na stranici Kontakt.','For questions about how your data is processed, contact your host using the telephone number on the Contact page.','Bei Fragen zur Verarbeitung Ihrer Daten erreichen Sie Ihren Gastgeber unter der Telefonnummer auf der Kontaktseite.')}</p>`:`<h2>${t('Smještaj i usluge','Accommodation and services','Unterkunft und Leistungen')}</h2><p>${t('Nazivi šest apartmana, kapaciteti, spavaće sobe i površine preuzeti su iz popisa domaćina. Cijene, dostupnost i ostale sadržaje potvrđuje domaćin.','Names, capacities, bedrooms and floor areas of the six apartments come from the host’s list. The host confirms prices, availability and other amenities.','Namen, Kapazitäten, Schlafzimmer und Flächen der sechs Apartments stammen aus der Gastgeberliste. Preise, Verfügbarkeit und weitere Ausstattung bestätigt der Gastgeber.')}</p><h2>${t('Upiti i rezervacije','Enquiries and reservations','Anfragen und Buchungen')}</h2><p>${t('Priprema upita ne znači slanje poruke niti potvrdu rezervacije. Rezervaciju, konačnu cijenu i uvjete plaćanja, otkazivanja i boravka dogovarate izravno s domaćinom prije potvrde rezervacije.','Preparing an enquiry does not send a message or confirm a reservation. Agree on the reservation, final price, payment, cancellation and stay conditions directly with your host before confirming your booking.','Das Vorbereiten einer Anfrage versendet keine Nachricht und bestätigt keine Buchung. Vereinbaren Sie Buchung, Endpreis sowie Zahlungs-, Storno- und Aufenthaltsbedingungen vor der Buchungsbestätigung direkt mit Ihrem Gastgeber.')}</p>${destinationPhotoCredits()}`}</div></section>`}
let currentPhotos=[],photoIndex=0,lastPhotoTrigger=null;
function showPhoto(key,category=null){currentPhotos=category?S.photos.filter(p=>p.category===category):Array.from(document.querySelectorAll('[data-photo]')).map(b=>image(b.dataset.photo));currentPhotos=currentPhotos.filter((p,i,a)=>a.findIndex(x=>x.key===p.key)===i);photoIndex=currentPhotos.findIndex(p=>p.key===key);lastPhotoTrigger=document.activeElement;const viewer=document.querySelector('#lightbox');viewer.setAttribute('aria-label',categories().find(c=>c[0]===category)?.[1]||t('Pregled fotografije','Photo viewer','Fotoansicht','Prohlížeč fotografií'));viewer.querySelector('.close-light').setAttribute('aria-label',t('Zatvori','Close','Schließen','Zavřít'));viewer.querySelector('.prev').setAttribute('aria-label',t('Prethodna fotografija','Previous photograph','Vorheriges Foto','Předchozí fotografie'));viewer.querySelector('.next').setAttribute('aria-label',t('Sljedeća fotografija','Next photograph','Nächstes Foto','Další fotografie'));updatePhoto();viewer.showModal()}
function updatePhoto(){const p=currentPhotos[photoIndex];if(!p)return;const d=document.querySelector('#lightbox');d.querySelector('img').src=p.url||'/assets/'+p.file;d.querySelector('img').alt=t(p.alt,p.altEn||'Apartment photograph',p.altDe||'Apartmentfoto',p.altCs);d.querySelector('figcaption').textContent=`${photoIndex+1} / ${currentPhotos.length} · ${categories().find(c=>c[0]===p.category)?.[1]||'Meleh'}`;d.querySelector('.prev').disabled=currentPhotos.length<2;d.querySelector('.next').disabled=currentPhotos.length<2}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function nextDay(v){const d=new Date(v+'T12:00:00');d.setDate(d.getDate()+1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function setupDates(form){const start=form.querySelector('[name=arrival]'),end=form.querySelector('[name=departure]');if(!start)return;start.min=today();end.min=today();function validate(){end.setCustomValidity('');end.min=start.value?nextDay(start.value):today();if(end.value&&start.value&&end.value<=start.value)end.setCustomValidity(t('Odlazak mora biti nakon dolaska.','Check-out must be after check-in.','Die Abreise muss nach der Anreise liegen.'))}start.addEventListener('change',validate);end.addEventListener('change',validate);validate()}
function render(){if(/^\/plan-dana\/?$/.test(location.pathname))history.replaceState({},'', '/vodic/'+location.search+location.hash);syncIdentity(S,document);lang=new URLSearchParams(location.search).get('lang')||'hr';if(!['hr','en','de','cs'].includes(lang))lang='hr';const path=decodeURIComponent(location.pathname).replace(/\/+$/,'')||'/';let body,title;const apartment=S.apartments.find(a=>path==='/apartmani/'+a.slug);if(path==='/'){body=home();title=t('Odmor u svom ritmu','A holiday at your pace','Urlaub in Ihrem Rhythmus')}else if(path==='/gost'){body=G.markup();title=t('Vodič za goste','Guest guide','Gästeführer')}else if(path==='/pronadi-apartman'){body=P.finderPage();title=t('Pronađi apartman','Find an apartment','Apartment finden')}else if(path==='/usporedba'){body=C.comparisonPage();title=t('Usporedba apartmana','Compare apartments','Apartmentvergleich')}else if(path==='/apartmani'){body=apartments();title=label('apartments')}else if(apartment){body=detail(apartment);title=apartment.name}else if(path==='/o-nama'){body=about();title=label('about')}else if(path==='/galerija'){body=gallery();title=label('gallery')}else if(path==='/kontakt'){body=contact();title=label('contact')}else if(path==='/admin'){body=F.adminPage();title='Administracija'}else if(path==='/vodic'){body=P.dayPage()+F.guidePage();title=t('Vodič','Guide','Reiseführer','Průvodce')}else if(path==='/kako-do-nas'){const copy=arrivalCopy(lang);body=pageHead(copy.title,copy.intro)+arrivalContent(S,lang);title=copy.title}else if(path==='/faq'){body=F.faqPage();title=t('Česta pitanja','FAQ','Häufige Fragen')}else if(path==='/dostupnost'){body=F.availabilityPage();title=t('Dostupnost','Availability','Verfügbarkeit')}else if(path==='/privatnost'||path==='/uvjeti'){body=legal(path==='/privatnost'?'privacy':'terms');title=t('Korisne informacije','Useful information','Nützliche Informationen')}else{title='404';body=pageHead(t('Stranica nije pronađena','Page not found','Seite nicht gefunden'))+`<section class="section wrap"><a class="btn" href="/">${label('home')} ↗</a></section>`}document.documentElement.lang=lang;document.querySelector('.skip').textContent=t('Preskoči na sadržaj','Skip to content','Zum Inhalt springen','Přejít k obsahu');updateSeoDocument(S,path,lang,document,{preview:window.MELEH_PREVIEW===true||new URLSearchParams(location.search).get('theme-preview')==='adria'});document.querySelector('#app').innerHTML=header()+F.previewBanner()+`<main id="main">${body}</main>`+(path==='/admin'?'':footer());document.querySelector('#text-size').addEventListener('change',e=>{applyTextSize(e.target.value,document.documentElement);requestAnimationFrame(updateMenuSpace)});document.querySelector('.language').addEventListener('change',e=>{lang=e.target.value;localStorage.setItem('meleh-language',lang);const address=new URL(location.href);if(lang==='hr')address.searchParams.delete('lang');else address.searchParams.set('lang',lang);history.replaceState({},'',address.pathname+address.search+address.hash);render()});document.querySelector('.menu-button').addEventListener('click',e=>{const nav=document.querySelector('.nav-links'),open=nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);e.currentTarget.textContent=open?'×':'☰';e.currentTarget.setAttribute('aria-label',open?t('Zatvori izbornik','Close menu','Menü schließen'):t('Otvori izbornik','Open menu','Menü öffnen'));if(open)updateMenuSpace()});document.querySelectorAll('.header nav a').forEach(a=>{if(a.pathname===location.pathname){a.classList.add('active');a.setAttribute('aria-current','page')}});const quick=document.querySelector('#availability');if(quick){setupDates(quick);quick.addEventListener('submit',e=>{e.preventDefault();navigate('/kontakt/?'+new URLSearchParams(new FormData(quick)).toString())})}const form=document.querySelector('#inquiry');if(form){const query=new URLSearchParams(location.search);for(const [key,val]of query){const field=form.elements[key==='apartman'?'apartment':key];if(field&&['apartment','adults','children'].includes(field.name))field.value=val}contactDates.bind(form);form.addEventListener('submit',submitInquiry)}document.querySelectorAll('a[href]').forEach(a=>{if(lang!=='hr'&&a.origin===location.origin&&!a.getAttribute('href').startsWith('#')&&!a.pathname.startsWith('/api/')){const next=new URL(a.href);if(!next.searchParams.has('lang'))next.searchParams.set('lang',lang);a.href=next.pathname+next.search+next.hash}});F.bind();C.bind();P.bind();G.bind();window.MelehTheme?.sync()}
async function submitInquiry(e){if(!contactDates.valid(e.currentTarget)){e.preventDefault();document.querySelector('#form-error').textContent=t('Odaberite datume dolaska i odlaska.','Choose your check-in and check-out dates.','Wählen Sie Anreise- und Abreisedatum.','Vyberte datum příjezdu a odjezdu.');e.currentTarget.querySelector('[data-booking-field="arrival"]').focus();return}if(e.currentTarget.dataset.mailReady==='true')return F.sendInquiry(e);return submitInquiryLocal(e)}
function submitInquiryLocal(e){e.preventDefault();const f=e.currentTarget;const error=document.querySelector('#form-error');error.textContent='';const data=Object.fromEntries(new FormData(f));if(!data.name.trim()){error.textContent=t('Unesite ime i prezime.','Please enter your full name.','Bitte geben Sie Ihren Namen ein.');f.elements.name.focus();return}if(data.arrival<today()||data.departure<=data.arrival){error.textContent=t('Provjerite datume dolaska i odlaska.','Please check your arrival and departure dates.','Bitte prüfen Sie Ihre Reisedaten.');return}const a=S.apartments.find(a=>a.slug===data.apartment);if(a&&Number(data.adults)+Number(data.children)>a.guests.split('+').reduce((n,v)=>n+Number(v.trim()),0)){error.textContent=t('Broj gostiju prelazi kapacitet apartmana. Odaberite drugi apartman ili opciju „Svejedno”.','Guest count exceeds this apartment’s capacity. Choose another apartment or “Any apartment”.','Die Gästezahl übersteigt die Kapazität. Wählen Sie ein anderes Apartment oder „Egal”.');return}const text=[t(`Upit za boravak — ${S.name}`,`Stay enquiry — ${S.name}`,`Aufenthaltsanfrage — ${S.name}`),' ',`${t('Ime','Name','Name')}: ${data.name.trim()}`,`E-mail: ${data.email}`,`${t('Telefon','Phone','Telefon')}: ${data.phone||'—'}`,`${t('Apartman','Apartment','Apartment')}: ${a?.name||t('Svejedno','Any','Egal')}`,`${t('Dolazak','Check-in','Anreise')}: ${data.arrival}`,`${t('Odlazak','Check-out','Abreise')}: ${data.departure}`,`${t('Odrasli','Adults','Erwachsene')}: ${data.adults}`,`${t('Djeca','Children','Kinder')}: ${data.children||0}`,'',data.message||''].join('\n');const result=document.querySelector('#inquiry-result');result.innerHTML=`<div class="inquiry-result"><h3>${t('Vaš upit je pripremljen.','Your enquiry is ready.','Ihre Anfrage ist vorbereitet.')}</h3><p class="section-note">${S.email?t('Otvorite ga u svojoj aplikaciji za e-poštu i pošaljite domaćinu.','Open it in your email app and send it to the host.','Öffnen Sie die Anfrage in Ihrer E-Mail-App und senden Sie sie an den Gastgeber.'):t('Upit nije poslan. Kontakt domaćina još nije unesen. Tekst možete kopirati ili preuzeti.','Your enquiry has not been sent. Host contact details have not been added yet. You can copy or download the text.','Die Anfrage wurde nicht versendet. Die Kontaktdaten fehlen noch. Sie können den Text kopieren oder herunterladen.')}</p><pre>${esc(text)}</pre><div class="actions">${S.email?`<a class="btn" href="mailto:${esc(S.email)}?subject=${encodeURIComponent(S.name+' — '+data.arrival)}&body=${encodeURIComponent(text)}">${t('Otvori e-poštu','Open email app','E-Mail öffnen')} ↗</a>`:''}<button class="btn" id="copy-inquiry">${t('Kopiraj upit','Copy enquiry','Anfrage kopieren')}</button><button class="btn outline" id="download-inquiry">${t('Preuzmi tekst','Download text','Text herunterladen')}</button></div><p id="copy-status" role="status" class="section-note"></p></div>`;document.querySelector('#copy-inquiry').onclick=async()=>{try{await navigator.clipboard.writeText(text);document.querySelector('#copy-status').textContent=t('Upit je kopiran.','Enquiry copied.','Anfrage kopiert.')}catch{document.querySelector('#copy-status').textContent=t('Kopiranje nije dostupno. Preuzmite tekst upita.','Copying unavailable. Download the enquiry text.','Kopieren nicht verfügbar. Laden Sie den Text herunter.')}};document.querySelector('#download-inquiry').onclick=()=>{const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='Adria-Maja-upit.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};result.scrollIntoView({behavior:'smooth',block:'center'})}
function navigate(href){const next=new URL(href,location.origin);if(lang!=='hr'&&!next.searchParams.has('lang'))next.searchParams.set('lang',lang);history.pushState({},'',next.pathname+next.search+next.hash);render();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const album=e.target.closest('[data-album]');if(album){const first=S.photos.find(p=>p.category===album.dataset.album);if(first)showPhoto(first.key,album.dataset.album);return}const p=e.target.closest('[data-photo]');if(p){showPhoto(p.dataset.photo);return}const a=e.target.closest('a');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||a.target||a.download||a.origin!==location.origin||!a.pathname.startsWith('/')||a.hash)return;if(a.protocol==='http:'||a.protocol==='https:'){e.preventDefault();navigate(a.pathname+a.search)}});
const lightbox=document.querySelector('#lightbox');lightbox.querySelector('.close-light').onclick=()=>lightbox.close();lightbox.addEventListener('close',()=>lastPhotoTrigger?.focus());lightbox.querySelector('.prev').onclick=()=>{photoIndex=(photoIndex-1+currentPhotos.length)%currentPhotos.length;updatePhoto()};lightbox.querySelector('.next').onclick=()=>{photoIndex=(photoIndex+1)%currentPhotos.length;updatePhoto()};lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowRight')lightbox.querySelector('.next').click();if(e.key==='ArrowLeft')lightbox.querySelector('.prev').click()});lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});window.addEventListener('hashchange',()=>{if(location.pathname.replace(/\/+$/,'')==='/gost')G.bind()});window.addEventListener('popstate',()=>{render();window.scrollTo(0,0)});render();let startupInput=false;document.addEventListener('input',()=>{startupInput=true},{once:true});F.init().then(changed=>{if(changed&&!startupInput&&!document.querySelector('input:focus,textarea:focus,select:focus'))render();else if(changed)contactDates.refresh(document.querySelector('#inquiry'))});


function destinationPhotoCredits(){return `<h2>${t('Fotografije','Photographs','Fotos')}</h2><p>${S.photoCredits.map(c=>`<a href="${esc(c.source)}" target="_blank" rel="noopener">${esc(c.title)}</a> — ${esc(c.author)}, <a href="${esc(c.licenseUrl)}" target="_blank" rel="license noopener">${esc(c.license)}</a>`).join('<br>')}</p><p>${t('Fotografije destinacije prilagođene su veličini prikaza, a pojedini prikazi koriste izrez i zatamnjenje. Prilagođeni prikazi dostupni su pod istom licencom kao izvornici.','Destination photographs are resized for display; some views use cropping and a dark overlay. Adapted displays are available under the same license as the originals.','Die Ortsfotos wurden für die Anzeige skaliert; einige Ansichten nutzen Ausschnitt und Abdunklung. Bearbeitete Darstellungen stehen unter derselben Lizenz wie die Originale.')}</p>`}


document.addEventListener('click',e=>{const control=document.querySelector('.text-size-control');if(control&&!control.contains(e.target))control.open=false});
document.addEventListener('keydown',e=>{const control=document.querySelector('.text-size-control');if(e.key==='Escape'&&control?.open){control.open=false;control.querySelector('summary').focus()}});

window.addEventListener('resize',updateMenuSpace);window.addEventListener('scroll',updateMenuSpace,{passive:true});window.visualViewport?.addEventListener('resize',updateMenuSpace);

function propertyDetails(){const facts={Kategorija:'category',Smještaj:'house','Ukupno soba u objektu':'rooms','Parking i internet':'parking',Uključeno:'included','Zajednički sadržaji':'gardenView','Za nautičare':'anchor',Plaže:'beach','Aktivnosti u okolici':'diving','Sadržaji koji nisu dostupni':'unavailable'},nearby={More:'seaView',Plaža:'beach',Restoran:'kitchen',Market:'groceries',Pošta:'post',Liječnik:'doctor',Bankomat:'atm',Ljekarna:'pharmacy','Autobusno stajalište':'bus','Benzinska postaja':'fuel'};const label=(f,keys)=>`<strong class="amenity-label">${amenityIcon(keys[f.label?.hr]||'info')}<span>${esc(F.tr(f.label))}</span></strong>`;return `<section class="section cream"><div class="wrap availability-layout property-details" style="--property-detail-rows:${Math.max((S.propertyFacts||[]).length,(S.nearby||[]).length)+1}"><div class="property-detail-group"><h2>${t('Kuća i zajednički sadržaji','The house and shared facilities','Das Haus und die gemeinsame Ausstattung')}</h2><div class="rule-list">${(S.propertyFacts||[]).map(f=>`<div>${label(f,facts)}<span>${esc(F.tr(f.value))}</span></div>`).join('')}</div></div><div class="property-detail-group"><h2>${t('Sve u blizini','Nearby essentials','Alles in der Nähe')}</h2><div class="rule-list">${(S.nearby||[]).map(f=>`<div>${label(f,nearby)}<span>${esc(f.distance)}</span></div>`).join('')}</div></div></div></section>`}
